101		fmt.Fprintln(outW, "Waiting for approval...")
102	
103		token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
104		if err != nil {
105			return fmt.Errorf("complete login: %w", err)
106		}
107	
108		if err := validateReceivedToken(token, client.BaseURL(), time.Now()); err != nil {
109			return fmt.Errorf("reject login token: %w", err)
110		}
111	
112		store := auth.NewStore()
113	
114		// Login deliberately uses the legacy SaveToken (string, string)
115		// surface — we only have an access-token string at this point;
116		// the deviceflow client doesn't return a TokenSet here.
117		if err := store.SaveToken(client.BaseURL(), token); err != nil {
118			return fmt.Errorf("save auth token: %w", err)
