199	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
200		expiry := time.Duration(expiresIn) * time.Second
201		if expiry <= 0 || expiry > maxExpiresIn {
202			expiry = maxExpiresIn
203		}
204		deadline := time.Now().Add(expiry)
205		pollInterval := interval
206		if pollInterval <= 0 {
207			pollInterval = fallbackDeviceAuthPollInterval
208		}
209	
210		consecutiveErrors := 0
211	
212		for {
213			if time.Now().After(deadline) {
214				return "", errors.New("device authorization expired")
215			}
216	
217			result, err := poller.PollDeviceAuth(ctx, deviceCode)
218			if err != nil {
219				consecutiveErrors++
220				if consecutiveErrors >= maxTransientErrors {
221					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
222				}
223				// Transient error — wait and retry.
224				select {
225				case <-ctx.Done():
226					return "", fmt.Errorf("wait for approval: %w", ctx.Err())
227				case <-time.After(pollInterval):
228				}
229				continue
230			}
231			consecutiveErrors = 0
232	
233			switch result.Error {
234			case "":
235				if result.AccessToken == "" {
236					return "", errors.New("device authorization completed without a token")
237				}
238				return result.AccessToken, nil
239			case "authorization_pending":
240				// no-op, will sleep and retry below
241			case "slow_down":
242				pollInterval += slowDownBackoff
243				if pollInterval > maxPollInterval {
244					pollInterval = maxPollInterval
245				}
246			case "access_denied":
247				return "", errors.New("device authorization denied")
248			case "expired_token":
249				return "", errors.New("device authorization expired")
250			default:
251				if result.ErrorDescription != "" {
252					return "", fmt.Errorf("device authorization failed: %s: %s", result.Error, result.ErrorDescription)
253				}
254				return "", fmt.Errorf("device authorization failed: %s", result.Error)
255			}
256	
257			select {
258			case <-ctx.Done():
259				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
260			case <-time.After(pollInterval):
261			}
262		}
263	}
