265	// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
266	// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
267	// Returns ctx.Err() if the context is cancelled before the user presses Enter.
268	func waitForEnter(ctx context.Context) error {
269		tty, err := os.Open("/dev/tty")
270		if err != nil {
271			return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
272		}
273	
274		done := make(chan error, 1)
275		go func() {
276			reader := bufio.NewReader(tty)
277			_, err := reader.ReadString('\n')
278			done <- err
279		}()
280	
281		select {
282		case <-ctx.Done():
283			// Close tty to unblock the reading goroutine.
284			_ = tty.Close()
285			return fmt.Errorf("interrupted: %w", ctx.Err())
286		case <-done:
287			_ = tty.Close()
288			return nil
289		}
290	}
